INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (69, 181, 'Tear clips tear band)', '../upload/image/20180826/20180826131849_33719.jpg', '<p></p><p>Packaging Rope (Tear clips tear band)</p> <p>Tear clips (tear band,tear tape,tear strip) for closing bags.<br/> The tear clip have two lines of steel/iron at clip''s its two sides.<br/> tear clips included Packaging Rope,Tear clips, tear band,tear tape,tear strip,PP/PE/PVC Tie lines,steel/iron lines clips,iron tear tape. Material of Tear clips: PP and PE.<br/> Outer Diameter of Tear clips - 33 cm<br/> Inner core of Tear clips: 14/6.5 CM -250 Clip line width:8MM <br/> Inner steel/iron diameter(two iron lines at clips'' two sides):0.7MM (or 0.65MM)<br/> Length of Tear clips rolls: 450,500,1000,1500M<br/> Color for tear clips: red, white, blue,black,yellow,color logo printed and so on. <br/> Packing of tear clips rolls: 6rolls/carton<br/> Quantity: 55000rolls/day</p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (69, 182, 'PP PET packing belt or strap', '../upload/image/20180826/20180826131924_58540.png', '<p></p><p>PP PET packing belt or strap</p> <p>PP/PET packing belt or strap were used for packing cartons and cargos during transportation, they have softy,hard,steel and plastic features.<br/> pp packing belt included PP strap, PP strapping tape,tying band,PP tear clip,plastic strap polyproplene blue colour,PP band,band-pp,Straps PP,Polyester strapping for packaging,PET strap <br/> Size 01 of PP/PET packing belts:12mm width x 0.60 thickness x 2000 mtr length core size 200mm <br/> Application:blue colour embossed for semi automatic machine and same size for fully automatic machine<br/> Size 02 of PP/PET packing belts:15mm x 0.70 x 900 mtr colour yellow embossed core size 200mm <br/> packing: 2 kg/roll,10 rolls/ctn <br/> Normal details sizes for PP/PET packing belts following<br/> NO. width thickness pulling force weight length inner core<br/> PP-0605 6mm 0.5mm 50kg 10kg 4000M 200mm<br/> PP-0906 9mm 0.6mm 130kg 10kg 2600M 200mm<br/> PP-0907 9mm 0.7mm 150kg 10kg 2280M 200mm<br/> PP-1206 12mm 0.6mm 170kg 10kg 2000M 200mm<br/> PP-1207 12mm 0.7mm 180kg 10kg 1750M 200mm<br/> PP-1306 13mm 0.6mm 200kg 10kg 1450M 200mm<br/> PP-1307 13mm 0.7mm 210kg 10kg 1200M 200mm<br/> PP-1506 15mm 0.6mm 220kg 10kg 1350M 200mm<br/> PP-1507 15mm 0.7mm 230kg 10kg 1150M 200mm<br/> PP-1908 19mm 0.8mm 280kg 10kg 900M 200mm</p>', '2026-09-06 20:58:45');